    {
      "component": "title",
      "props": {
        "eyebrow": "Quarterly Risk Review",
        "headline": "Top Operational Risks Requiring Attention",
        "accent": "primary"
      }
    },
    {
      "component": "bullet-list",
      "props": {
        "heading": "Key Risk Areas",
        "items": [
          "Vendor concentration: heavy reliance on a small number of critical suppliers increases exposure to disruption",
          "On-call fatigue: sustained incident load is straining engineering response capacity",
          "Single-region failover gap: lack of multi-region redundancy risks extended outages",
          "Unpatched CVE backlog: accumulating known vulnerabilities elevate security exposure"
        ]
      }
    }
  ]
}

